import java.util.HashSet;
import java.util.Scanner;

public class Main {
    static long[] par;

    static long getPar(long x) {
        if (par[(int) x] == x) return x;
        return par[(int) x] = getPar(par[(int) x]);
    }

    static void Union(long x, long y) {
        if (getPar(x) == getPar(y)) return;
        par[(int) getPar(x)] = getPar(y);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        par = new long[(int) p];
        for (int i = 0; i < p; i++) {
            par[i] = i;
        }

        for (long i = 1; i < p; i++) {
            if ((k * i) % p != 0) {
                Union((k * i) % p, i);
            }
        }

        HashSet<Long> seen = new HashSet<>();
        for (long i = 1; i < p; i++) {
            seen.add(getPar(i));
        }

        long pw = seen.size();
        if (k == 1) pw = p;

        long blah = 1;
        long mod = 1000000007L;
        for (long i = 0; i < pw; i++) {
            blah = (blah * p) % mod;
        }
        System.out.println(blah);
        sc.close();
    }
}
